#!/usr/bin/env python3
"""Render thin independent workflow definitions from the reviewed job defaults."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def render(job, config):
    refill = job == 'refill'
    name = 'Database refill (manual only)' if refill else f'Data {job.replace("_", " ")}'
    filename = 'database-refill.yml' if refill else ('data-dataset-build.yml' if job == 'datasets' else f'data-update-{job.replace("_", "-")}.yml')
    schedule = '' if refill else f'''  # Nonproduction only; opt-in at repository level. No production schedule exists.
  schedule:
    - cron: '{config["cron"]}'
'''
    extra = '''      resume:
        description: Resume the SAME committed initial/backfill scope
        type: boolean
        default: false
      jobs:
        description: Space-separated jobs (blank means all sources; datasets when configured)
        type: string
      max_partitions:
        description: New job/season partitions per dispatch (1-1000)
        type: number
        default: 8
''' if refill else ''
    condition = "github.event_name == 'workflow_dispatch'" if refill else "github.event_name == 'workflow_dispatch' || (github.event_name == 'schedule' && vars.DATA_NONPROD_SCHEDULES_ENABLED == 'true')"
    content = f'''# Generated by .github/scripts/generate_data_workflows.py; edit defaults there/in data-jobs.json.
name: {name}

on:
{schedule}  workflow_dispatch:
    inputs:
      environment:
        description: Explicit GitHub Environment
        required: true
        type: choice
        options: [nonprod, prod]
      target_id:
        description: Prepared database target UUID (must match Environment DATA_TARGET_ID)
        required: true
        type: string
      current_season:
        description: Season start year (blank resolves current NHL standings at runtime)
        type: string
      first_season:
        description: First year (blank means {'2008' if refill else 'current season'})
        type: string
      last_season:
        description: Last year (blank means current season)
        type: string
      validation_only:
        description: Validate without writing data or acknowledging events
        type: boolean
        default: true
{extra}
permissions:
  contents: read

# Complement the database reservations; independent jobs can run concurrently.
concurrency:
  group: data-{job}-${{{{ inputs.environment || 'nonprod' }}}}
  cancel-in-progress: false

jobs:
  execute:
    if: ${{{{ {condition} }}}}
    runs-on: ${{{{ vars.DATA_RUNNER || 'ubuntu-latest' }}}}
    timeout-minutes: 330
    environment: ${{{{ inputs.environment || 'nonprod' }}}}
    steps:
      - uses: actions/checkout@v4
        with:
          persist-credentials: false
      - name: Verify approved code and explicit target before exposing database credentials
        id: guard
        env:
          GH_TOKEN: ${{{{ github.token }}}}
          DATA_ENVIRONMENT: ${{{{ inputs.environment || 'nonprod' }}}}
          DATA_REQUESTED_TARGET: ${{{{ inputs.target_id }}}}
          DATA_TARGET_ID: ${{{{ vars.DATA_TARGET_ID }}}}
          DATA_APPROVED_SHA: ${{{{ vars.DATA_APPROVED_SHA }}}}
          DATA_NONPROD_SCHEDULES_ENABLED: ${{{{ vars.DATA_NONPROD_SCHEDULES_ENABLED }}}}
          DATA_NOTIFICATION_OWNER: ${{{{ vars.DATA_NOTIFICATION_OWNER }}}}
        run: python3 .github/scripts/data_workflow_guard.py
      - name: Check out the approved immutable commit
        uses: actions/checkout@v4
        with:
          ref: ${{{{ steps.guard.outputs.sha }}}}
          persist-credentials: false
      - name: Run existing pipeline entrypoints
        uses: ./.github/actions/data-job
        with:
          job: {job}
          environment: ${{{{ inputs.environment || 'nonprod' }}}}
          target-id: ${{{{ vars.DATA_TARGET_ID }}}}
          database-url: ${{{{ secrets.DATABASE_URL }}}}
          current-season: ${{{{ inputs.current_season }}}}
          first-season: ${{{{ inputs.first_season }}}}
          last-season: ${{{{ inputs.last_season }}}}
          validation-only: ${{{{ github.event_name == 'workflow_dispatch' && inputs.validation_only || false }}}}
          resume: ${{{{ inputs.resume || false }}}}
          jobs: ${{{{ inputs.jobs }}}}
          max-partitions: ${{{{ inputs.max_partitions || 8 }}}}
          enabled: ${{{{ vars.DATA_{job.upper()}_ENABLED }}}}
          lookback-days: ${{{{ vars.DATA_{job.upper()}_LOOKBACK_DAYS }}}}
          max-input-age-seconds: ${{{{ vars.DATA_{job.upper()}_MAX_INPUT_AGE_SECONDS }}}}
          max-batches: ${{{{ vars.DATA_{job.upper()}_MAX_BATCHES || 10000 }}}}
          dataset-config: ${{{{ vars.DATA_DATASET_CONFIG }}}}
          coverage-config: ${{{{ vars.DATA_COVERAGE_CONFIG }}}}
          artifact-root: ${{{{ vars.DATA_ARTIFACT_ROOT }}}}
      - name: Retain sanitized completion report
        if: ${{{{ always() }}}}
        uses: actions/upload-artifact@v4
        with:
          name: data-{job}-${{{{ github.run_id }}}}-${{{{ github.run_attempt }}}}
          path: coverage/data-workflow/report.json
          if-no-files-found: warn
          retention-days: 14
'''
    if not refill:
        content = content.replace("${{ inputs.resume || false }}", "'false'").replace("${{ inputs.jobs }}", "''").replace("${{ inputs.max_partitions || 8 }}", "'8'")
    return filename, content


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    configs = json.loads((ROOT / '.github/data-jobs.json').read_text())
    for job, config in [*configs.items(), ('refill', {})]:
        filename, content = render(job, config)
        path = ROOT / '.github/workflows' / filename
        if args.check:
            if not path.exists() or path.read_text() != content:
                raise SystemExit(f'Workflow drift: {filename}; run {Path(__file__).name}')
        else:
            path.write_text(content)


if __name__ == '__main__':
    main()
